/* ==========================================================
   Launchpad diagrams (KS3). New figures plus re-captioned versions of the shared ones.
   All colours come from theme tokens so both themes read.
   ========================================================== */
const WATER = 'color-mix(in srgb, var(--u5) 20%, transparent)', WATERL = 'color-mix(in srgb, var(--u5) 55%, transparent)';
const GLASS = 'color-mix(in srgb, var(--u10) 14%, transparent)';
/* re-caption a shared diagram; fix() can edit its SVG first */
const recap = (k, text, fix) => () => { let s = DIAG[k](); if (fix) s = fix(s); return s.replace(/<figcaption>[\s\S]*?<\/figcaption>/, '') + cap(text); };
/* formula triangle: top over (left × right) */
const tri = (top, l, r, label, eqs) => { let s = pth('M110,14 L200,160 L20,160 Z', INK, 2, 'var(--surface)') + ln(58, 98, 162, 98, INK, 2) + ln(110, 98, 110, 160, INK, 2);
  s += tx(110, 76, top, { a: 'middle', fs: 24, c: C1, w: 700, f: 'var(--f-math)', it: true }) + tx(66, 140, l, { a: 'middle', fs: 24, c: C5, w: 700, f: 'var(--f-math)', it: true }) + tx(154, 140, r, { a: 'middle', fs: 24, c: C3, w: 700, f: 'var(--f-math)', it: true }) + tx(110, 139, '×', { a: 'middle', fs: 16, c: MUT });
  eqs.forEach((e, i) => s += tx(240, 50 + i * 36, e, { fs: 16, c: INK, f: 'var(--f-math)' }));
  return svg(440, 175, s, label) + cap('Cover the quantity you want to find. Side by side → multiply; one above the other → divide.'); };
const magnet = (x, y, w, h, nLeft = true, lab = true) => box(x, y, w / 2, h, nLeft ? C1 : C6, INK, 2, 1.6) + box(x + w / 2, y, w / 2, h, nLeft ? C6 : C1, INK, 2, 1.6) + (lab ? tx(x + w / 4, y + h / 2 + 5, nLeft ? 'N' : 'S', { a: 'middle', fs: 14, c: '#fff', w: 700 }) + tx(x + 3 * w / 4, y + h / 2 + 5, nLeft ? 'S' : 'N', { a: 'middle', fs: 14, c: '#fff', w: 700 }) : '');
const person = (x, y, s = 1, c = INK) => circ(x, y - 38 * s, 7 * s, 'var(--surface)', c, 1.6) + ln(x, y - 31 * s, x, y - 12 * s, c, 1.8) + ln(x, y - 12 * s, x - 7 * s, y, c, 1.8) + ln(x, y - 12 * s, x + 7 * s, y, c, 1.8) + ln(x - 9 * s, y - 25 * s, x + 9 * s, y - 25 * s, c, 1.8);
const eyeIcon = (x, y, c = INK) => pth(`M${x - 14},${y} Q${x},${y - 11} ${x + 14},${y} Q${x},${y + 11} ${x - 14},${y} Z`, c, 1.6, 'var(--surface)') + circ(x, y, 4.5, c, c, 1);
const sun = (x, y, r = 16) => circ(x, y, r, '#FFC24B', '#E8A317', 1.5) + Array.from({ length: 8 }, (_, i) => { const a = i * Math.PI / 4; return ln(x + Math.cos(a) * (r + 4), y + Math.sin(a) * (r + 4), x + Math.cos(a) * (r + 11), y + Math.sin(a) * (r + 11), '#E8A317', 2); }).join('');

Object.assign(DIAG, {
  /* ---------- formula triangles ---------- */
  triangle: () => tri('W', 'm', 'g', 'Formula triangle for weight', ['W = m × g', 'm = W ÷ g', 'g = W ÷ m']),
  tri_weight: () => tri('W', 'm', 'g', 'Formula triangle for weight', ['W = m × g', 'm = W ÷ g', 'g = W ÷ m']),
  tri_density: () => tri('m', 'ρ', 'V', 'Formula triangle for density', ['ρ = m ÷ V', 'm = ρ × V', 'V = m ÷ ρ']),
  tri_speed: () => tri('d', 'v', 't', 'Formula triangle for speed', ['v = d ÷ t', 'd = v × t', 't = d ÷ v']),
  tri_ohm: () => tri('V', 'I', 'R', 'Formula triangle for resistance', ['R = V ÷ I', 'V = I × R', 'I = V ÷ R']),

  /* ---------- Unit 1 ---------- */
  contact: () => { let s = tx(130, 18, 'CONTACT — objects touch', { a: 'middle', fs: 12, c: C1, w: 700 }) + tx(430, 18, 'NON-CONTACT — act across a gap', { a: 'middle', fs: 12, c: C7, w: 700 });
    s += ln(280, 26, 280, 205, LN, 1, '4 4');
    // friction
    s += ln(12, 78, 118, 78, INK, 2) + box(38, 54, 44, 24, 'var(--surface-2)') + arrow(82, 66, 110, 66, C5, 2) + arrow(38, 72, 16, 72, C1, 2) + tx(65, 96, 'friction', { a: 'middle', c: INK, fs: 11.5 });
    // air resistance (parachute)
    s += pth('M160,58 Q190,28 220,58 Z', C2, 1.6, 'color-mix(in srgb, var(--u2) 25%, transparent)') + ln(162, 58, 190, 80, MUT, 1) + ln(218, 58, 190, 80, MUT, 1) + circ(190, 84, 5, INK, INK) + arrow(190, 40, 190, 26, C1, 2) + tx(190, 100, 'air resistance', { a: 'middle', c: INK, fs: 11.5 });
    // upthrust (boat)
    s += `<rect x="12" y="160" width="110" height="36" fill="${WATER}"/>` + pth('M40,150 L94,150 L86,164 L48,164 Z', INK, 1.6, 'var(--surface)') + arrow(67, 186, 67, 150, C5, 2) + tx(67, 140, 'upthrust', { a: 'middle', c: INK, fs: 11.5 });
    // tension (lamp)
    s += ln(160, 118, 240, 118, INK, 2) + ln(200, 118, 200, 160, MUT, 1.4) + pth('M186,160 L214,160 L206,172 L194,172 Z', INK, 1.4, '#FFC24B') + arrow(200, 150, 200, 126, C1, 2) + tx(200, 190, 'tension', { a: 'middle', c: INK, fs: 11.5 });
    // normal (book)
    // gravity
    s += circ(330, 170, 28, 'color-mix(in srgb, var(--u3) 30%, transparent)', C3) + circ(330, 72, 7, C1, INK, 1) + arrow(330, 82, 330, 128, C1, 2) + tx(330, 118, '', {}) + tx(360, 108, 'gravity (weight)', { c: INK, fs: 11.5 });
    // magnetic
    s += magnet(410, 58, 60, 18, true) + magnet(484, 58, 60, 18, false) + tx(477, 94, 'magnetic', { a: 'middle', c: INK, fs: 11.5 }) + arrow(466, 67, 474, 67, C7, 1.6) + arrow(488, 67, 480, 67, C7, 1.6);
    // electrostatic
    s += `<ellipse cx="440" cy="160" rx="18" ry="22" fill="color-mix(in srgb, var(--u11) 35%, transparent)" stroke="${INK}" stroke-width="1.5"/>` + tx(440, 165, '− −', { a: 'middle', fs: 11, c: INK }) + pth('M470,186 Q476,160 500,150 M474,190 Q484,166 506,158 M478,194 Q492,174 512,166', MUT, 1.3) + tx(480, 212, 'electrostatic', { a: 'middle', c: INK, fs: 11.5 });
    return svg(560, 220, s, 'Contact and non-contact forces') + cap('Contact forces need the objects to touch. Non-contact forces — gravity, magnetism and electrostatic forces — act across a gap.'); },
  arrows: () => { let s = box(70, 60, 70, 46, 'var(--surface-2)') + arrow(140, 83, 260, 83, C5, 3) + tx(200, 74, 'push 60 N', { a: 'middle', c: C5, w: 700 }) + arrow(70, 83, 40, 83, C1, 3) + tx(40, 74, '15 N', { a: 'middle', c: C1, w: 700 }) + tx(40, 104, 'friction', { a: 'middle', fs: 11 });
    s += box(330, 60, 70, 46, 'var(--surface-2)') + arrow(400, 83, 460, 83, C5, 3) + tx(430, 74, '30 N', { a: 'middle', c: C5, w: 700 }) + arrow(365, 60, 365, 12, C3, 3) + tx(372, 28, '40 N', { c: C3, w: 700 });
    s += tx(165, 138, 'longer arrow = bigger force', { a: 'middle', fs: 12, c: INK }) + tx(395, 138, 'arrowhead = direction', { a: 'middle', fs: 12, c: INK });
    return svg(500, 150, s, 'Force arrows') + cap('Force arrows start on the object. The length shows the size of the force; the head shows its direction. Label each with its name and size in newtons.'); },
  k_freebody: recap('freebody', 'A force diagram for a box being pulled along the floor: weight down, the normal (reaction) force up, the pull forwards and friction backwards. The vertical forces balance.'),
  balanced: () => { let s = tx(130, 18, 'BALANCED', { a: 'middle', fs: 13, c: GOOD, w: 700 }) + tx(410, 18, 'UNBALANCED', { a: 'middle', fs: 13, c: BAD, w: 700 });
    s += ln(20, 110, 240, 110, INK, 2) + pth('M80,86 L180,86 L190,100 L190,110 L70,110 L70,100 Z', INK, 1.6, 'var(--surface-2)') + circ(96, 110, 8, INK) + circ(164, 110, 8, INK) + arrow(190, 96, 244, 96, C5, 3) + arrow(70, 96, 16, 96, C1, 3) + tx(222, 88, '2000 N', { a: 'middle', c: C5, fs: 11 }) + tx(38, 88, '2000 N', { a: 'middle', c: C1, fs: 11 }) + tx(130, 138, 'steady speed (or stays still)', { a: 'middle', c: INK, fs: 12 });
    s += ln(300, 110, 520, 110, INK, 2) + pth('M360,86 L460,86 L470,100 L470,110 L350,110 L350,100 Z', INK, 1.6, 'var(--surface-2)') + circ(376, 110, 8, INK) + circ(444, 110, 8, INK) + arrow(470, 96, 536, 96, C5, 3) + arrow(350, 96, 322, 96, C1, 3) + tx(508, 88, '3000 N', { a: 'middle', c: C5, fs: 11 }) + tx(334, 88, '1000 N', { a: 'middle', c: C1, fs: 11 }) + tx(410, 138, 'speeds up (resultant 2000 N forwards)', { a: 'middle', c: INK, fs: 12 });
    return svg(550, 150, s, 'Balanced and unbalanced forces') + cap('Balanced forces: no change in motion. Unbalanced forces: the object speeds up, slows down or changes direction, in the direction of the bigger force.'); },
  k_terminal: recap('terminal', 'Speed of a skydiver: (1) weight > air resistance, she speeds up; (2) air resistance = weight, steady terminal velocity; (3) the parachute opens, air resistance > weight, she slows down; (4) balanced again at a slower, safe speed.'),
  canister: () => { let s = ''; const stage = (x, t, body) => { s += tx(x, 18, t, { a: 'middle', fs: 11.5, c: INK, w: 700 }) + body; };
    const can = (x, y, fill, lid = true) => box(x - 16, y, 32, 44, 'var(--surface)', INK, 3) + `<rect x="${x - 14}" y="${y + 44 - fill}" width="28" height="${fill}" fill="${WATER}"/>` + (lid ? box(x - 18, y + 44, 36, 6, 'var(--surface-2)', INK, 2) : '');
    s += ln(10, 170, 550, 170, INK, 2);
    stage(70, '1. Water + tablet', can(70, 120, 14) + `<rect x="64" y="150" width="12" height="6" fill="#fff" stroke="${INK}"/>` + tx(70, 196, 'lid down', { a: 'middle', fs: 11 }));
    stage(200, '2. Gas builds up', can(200, 120, 14) + [[192, 130], [205, 138], [198, 146], [210, 126]].map(([x, y]) => circ(x, y, 3, 'var(--surface)', C4, 1.2)).join('') + arrow(200, 132, 200, 116, C1, 1.4) + arrow(214, 140, 222, 140, C1, 1.4) + arrow(186, 140, 178, 140, C1, 1.4) + tx(200, 196, 'pressure rises', { a: 'middle', fs: 11 }));
    stage(340, '3. Lid pops', can(340, 60, 6, false) + box(322, 158, 36, 6, 'var(--surface-2)', INK, 2) + pth('M332,104 L324,150 M340,104 L340,152 M348,104 L356,150', C5, 2, 'none', '3 3') + arrow(340, 58, 340, 30, C3, 3) + tx(360, 40, 'thrust', { c: C3, fs: 11.5, w: 700 }) + tx(340, 196, 'water and gas pushed down', { a: 'middle', fs: 11 }));
    stage(480, '4. Thrust > weight', can(480, 70, 4, false) + arrow(480, 68, 480, 34, C3, 3) + arrow(480, 114, 480, 138, C1, 2) + tx(492, 134, 'weight', { c: C1, fs: 11 }) + tx(480, 196, 'unbalanced → lift-off', { a: 'middle', fs: 11 }));
    return svg(560, 205, s, 'How a film-canister rocket works') + cap('Carbon dioxide builds up until the pressure pops the lid. The canister pushes water and gas down; they push the canister up (thrust). Thrust is bigger than weight, so it lifts off.'); },

  /* ---------- Unit 2 ---------- */
  k_resultant: recap('resultant', 'Forces in opposite directions subtract; the resultant acts in the direction of the larger force. Here 3000 N forwards − (800 N + 400 N) backwards = 1800 N forwards.'),
  tugofwar: () => { let s = ln(20, 118, 540, 118, INK, 1.5) + ln(80, 90, 480, 90, '#B87333', 4);
    [60, 100, 140].forEach(x => s += person(x, 118, 1, C1)); [420, 460, 500].forEach(x => s += person(x, 118, 1, C5));
    s += ln(280, 80, 280, 100, INK, 2) + arrow(200, 60, 80, 60, C1, 3) + tx(140, 50, 'Team A: 1200 N', { a: 'middle', c: C1, w: 700 }) + arrow(360, 60, 460, 60, C5, 2.4) + tx(410, 50, 'Team B: 1000 N', { a: 'middle', c: C5, w: 700 }) + arrow(300, 140, 260, 140, INK, 2.4) + tx(280, 160, 'resultant 200 N to the left', { a: 'middle', c: INK, w: 700 });
    return svg(560, 170, s, 'Tug of war') + cap('Forces in opposite directions subtract: 1200 N − 1000 N = 200 N towards team A, so the rope starts to move towards team A.'); },
  newtonmeter: () => { let s = box(100, 20, 60, 220, 'var(--surface-2)', INK, 10) + ln(130, 6, 130, 20, INK, 2) + circ(130, 6, 4, 'none', INK, 1.6);
    for (let i = 0; i <= 10; i++) { const y = 40 + i * 16; s += ln(142, y, 156, y, INK, 1.4) + (i % 2 === 0 ? tx(166, y + 4, i, { fs: 11, f: 'var(--f-mono)' }) : ''); for (let j = 1; j < 4 && i < 10; j++) s += ln(148, y + j * 4, 156, y + j * 4, MUT, .8); }
    s += pth('M130,26 l-10,6 l20,6 l-20,6 l20,6 l-20,6 l20,6 l-20,6 l20,6 l-20,6 l20,6 l-10,6', C2, 2) + ln(118, 98, 150, 98, C1, 2.5) + ln(130, 98, 130, 250, INK, 2) + pth('M130,250 q0,12 -8,12 q-8,0 -8,-8', INK, 2);
    s += tx(210, 30, 'spring: stretches more', { c: INK }) + tx(210, 46, 'for a bigger force', { c: INK }) + tx(210, 100, 'pointer — read at eye level', { c: C1 }) + tx(210, 136, 'scale in newtons (N)', { c: INK }) + tx(210, 152, 'here: 0.25 N per division', { c: MUT, fs: 11 }) + tx(210, 256, 'hook: hang the object here', { c: INK }) + arrow(206, 99, 160, 99, C1, 1.2);
    s += tx(210, 196, 'reading: 3.5 N', { c: C2, w: 700, fs: 14 });
    return svg(420, 272, s, 'A newton meter') + cap('A newton meter: the spring stretches in proportion to the force, moving the pointer along a scale in newtons. Zero it first and choose a sensible range.'); },
  k_hooke: recap('hooke', 'Force–extension graph for a spring: a straight line through the origin (extension is proportional to force — Hooke’s law) up to the limit of proportionality. Beyond it the spring stretches more and may stay stretched.', s => s.replace(/<text[^>]*>area = energy stored<\/text>/, '').replace(/<text[^>]*>gradient = k<\/text>/, '')),
  popper: () => { let s = ln(20, 200, 540, 200, INK, 2) + box(40, 60, 14, 140, 'var(--surface-2)') + box(20, 196, 60, 8, 'var(--surface-2)') + box(54, 110, 40, 12, 'var(--surface-2)');
    s += pth('M94,104 L150,116 L94,128 Z', INK, 1.6, 'color-mix(in srgb, var(--u11) 40%, transparent)') + ln(150, 116, 300, 116, INK, 1.4);
    s += box(300, 104, 150, 24, 'var(--surface-2)', INK, 10) + ln(300, 116, 290, 116, INK, 1.6) + pth('M455,116 l14,0', INK, 2) + tx(375, 146, 'newton meter (zeroed)', { a: 'middle', fs: 11.5 }) + arrow(470, 116, 530, 116, C5, 3) + tx(500, 104, 'pull slowly', { a: 'middle', c: C5, fs: 11.5 });
    s += tx(170, 70, 'party popper, clamped,', { a: 'middle', fs: 11.5, c: INK }) + tx(170, 84, 'pointing away from people', { a: 'middle', fs: 11.5, c: INK }) + tx(240, 176, 'record the highest reading just before it pops', { a: 'middle', fs: 12, c: C2, w: 700 });
    return svg(560, 212, s, 'Measuring the force to pop a party popper') + cap('Clamp the popper, pull its string with a newton meter slowly and steadily, and record the peak force. Repeat with several poppers and find the mean.'); },

  /* ---------- Unit 3 ---------- */
  massweight: () => { let s = tx(130, 18, 'MASS (kg) — a balance', { a: 'middle', c: C3, w: 700 }) + tx(410, 18, 'WEIGHT (N) — a newton meter', { a: 'middle', c: C1, w: 700 });
    s += box(70, 130, 120, 36, 'var(--surface-2)') + box(90, 110, 80, 20, 'var(--surface)') + box(106, 80, 48, 30, C3) + tx(130, 100, '2 kg', { a: 'middle', c: '#fff', w: 700 }) + box(88, 140, 84, 18, 'var(--surface)', INK, 3) + tx(130, 153, '2.000 kg', { a: 'middle', f: 'var(--f-mono)', c: INK, fs: 12 });
    s += ln(410, 30, 410, 44, INK, 2) + box(394, 44, 32, 80, 'var(--surface-2)', INK, 8) + ln(402, 96, 418, 96, C1, 2.4) + ln(410, 124, 410, 140, INK, 1.6) + box(386, 140, 48, 30, C1) + tx(410, 160, '2 kg', { a: 'middle', c: '#fff', w: 700 }) + tx(440, 100, '20 N on Earth', { c: INK, w: 700 }) + arrow(410, 172, 410, 204, C1, 2.4) + tx(418, 200, 'W = m × g', { c: C1, fs: 12 });
    s += tx(130, 194, 'the same everywhere', { a: 'middle', c: INK }) + tx(410, 222, '3.2 N on the Moon · 50 N on Jupiter', { a: 'middle', c: MUT, fs: 11.5 });
    return svg(540, 232, s, 'Mass and weight') + cap('Mass is the amount of matter (kg), measured with a balance — it is the same everywhere. Weight is the force of gravity on it (N), measured with a newton meter — it depends on g.'); },
  wmgraph: () => plot({ w: 460, h: 260, x: [0, 1], y: [0, 10], xt: [0, .2, .4, .6, .8, 1], yt: [0, 2, 4, 6, 8, 10], xl: 'mass / kg', yl: 'weight / N', fns: [{ f: x => 10 * x, c: C3 }], marks: [.1, .2, .3, .4, .5, .6, .7, .8].map(m => ({ x: m, y: 10 * m, r: 3.5, c: C1 })), text: [[.55, 8.4, 'gradient = 10 N/kg = g', { c: C3, w: 700 }]], label: 'Weight against mass', cap: 'Weight is directly proportional to mass: a straight line through the origin. The gradient is the gravitational field strength, g = 10 N/kg on Earth.' }),
  gbars: () => { const P = [['Moon', 1.6], ['Mercury', 3.7], ['Mars', 3.7], ['Venus', 8.9], ['Earth', 10], ['Saturn', 10.4], ['Neptune', 11], ['Jupiter', 25]], H = 190, base = 210, sc = 7; let s = ln(40, base, 540, base, INK, 1.4);
    P.forEach(([n, g], i) => { const x = 52 + i * 60; s += bar(x, base, 40, g * sc, n === 'Earth' ? C5 : n === 'Jupiter' ? C2 : C3, n, g); });
    s += tx(40, 16, 'gravitational field strength g (N/kg)', { c: INK, fs: 12 });
    return svg(560, 232, s, 'Gravitational field strength on different worlds') + cap('g on the surface (or cloud tops) of each world. Your weight = your mass × g, so a 50 kg student weighs 80 N on the Moon but 1250 N on Jupiter.'); },

  /* ---------- Unit 4 ---------- */
  samesize: () => { let s = ''; [['cork', 0.24, C2, 4], ['wood', 0.7, '#B87333', 10], ['aluminium', 2.7, '#9AA3AC', 22], ['iron', 7.9, '#5B6C79', 40]].forEach(([n, d, c, k], i) => { const x = 30 + i * 130; s += box(x, 40, 70, 70, c, INK, 4) + tx(x + 35, 132, n, { a: 'middle', c: INK, w: 700 }) + tx(x + 35, 150, d + ' g/cm³', { a: 'middle', f: 'var(--f-mono)', fs: 11.5 }) + tx(x + 35, 168, Math.round(d * 1000) + ' g for 1000 cm³', { a: 'middle', fs: 10.5 }); for (let j = 0; j < Math.min(k, 49); j++) s += circ(x + 8 + (j % 7) * 9, 48 + Math.floor(j / 7) * 9, 3, 'rgba(255,255,255,.55)', 'none'); });
    return svg(540, 180, s, 'Same size, different mass') + cap('Four 10 cm cubes: the same volume but very different masses. The denser the material, the more mass is packed into each cubic centimetre.'); },
  k_states: recap('states', 'Solid: particles close together in a regular pattern. Liquid: still close but random, able to move past each other. Gas: far apart and fast — so a gas is far less dense than the same substance as a solid or liquid.'),
  displace: () => { let s = ''; const cyl = (x, lvl, lab, stone) => { let t = pth(`M${x},30 L${x},200 Q${x},208 ${x + 8},208 L${x + 52},208 Q${x + 60},208 ${x + 60},200 L${x + 60},30`, INK, 1.8) + `<rect x="${x + 1}" y="${lvl}" width="58" height="${207 - lvl}" fill="${WATER}"/>` + pth(`M${x + 1},${lvl} Q${x + 30},${lvl + 5} ${x + 59},${lvl}`, WATERL, 1.4);
      for (let v = 0; v <= 100; v += 10) { const y = 200 - v * 1.6; t += ln(x + 44, y, x + 60, y, INK, 1) + (v % 20 === 0 ? tx(x + 66, y + 4, v, { fs: 10, f: 'var(--f-mono)' }) : ''); }
      if (stone) t += ln(x + 30, 10, x + 30, 180, MUT, 1) + `<ellipse cx="${x + 30}" cy="188" rx="14" ry="10" fill="#8C7A6B" stroke="${INK}"/>`;
      return t + tx(x + 30, 228, lab, { a: 'middle', c: INK, w: 700 }); };
    s += cyl(60, 200 - 50 * 1.6, 'before: 50 cm³', false) + cyl(260, 200 - 62 * 1.6, 'after: 62 cm³', true) + arrow(160, 120, 240, 120, MUT, 1.5);
    s += tx(420, 110, 'volume of stone', { c: INK, w: 700 }) + tx(420, 128, '= 62 − 50', { c: INK }) + tx(420, 146, '= 12 cm³', { c: C4, w: 700, fs: 15 });
    return svg(540, 240, s, 'Volume by displacement') + cap('An irregular object pushes aside (displaces) its own volume of water. Read the bottom of the meniscus at eye level before and after; the difference is its volume.'); },
  k_eureka: recap('eureka', 'A eureka (displacement) can: fill it until water drips from the spout, then lower the object in. The water collected in the measuring cylinder equals the volume of the object.'),
  meniscus: () => { let s = pth('M40,20 L40,150 M160,20 L160,150', INK, 2) + `<rect x="41" y="80" width="118" height="70" fill="${WATER}"/>` + pth('M41,70 Q46,80 60,82 L140,82 Q154,80 159,70', WATERL, 2.5);
    [60, 70, 80, 90, 100, 110].forEach((v, i) => { const y = 130 - i * 16; s += ln(140, y, 160, y, INK, 1.2) + tx(170, y + 4, 60 + i * 2 + '', { fs: 11, f: 'var(--f-mono)' }); });
    s += eyeIcon(340, 84) + ln(160, 82, 326, 82, C1, 1.4, '5 4') + tx(250, 76, 'eye level', { a: 'middle', c: C1, fs: 11.5 }) + tx(200, 118, 'read the bottom of the curve:', { c: INK, fs: 12 }) + tx(200, 134, '66 cm³', { c: INK, fs: 12, w: 700 });
    return svg(380, 160, s, 'Reading a meniscus') + cap('Water curves up at the edges of a measuring cylinder. Put your eye level with the surface and read the bottom of the meniscus.'); },
  tower: () => { const L = [['vegetable oil', 0.92, '#E8C547'], ['water', 1.0, 'color-mix(in srgb, var(--u5) 45%, transparent)'], ['washing-up liquid', 1.06, '#5BB56A'], ['honey', 1.42, '#C9861A']]; let s = pth('M120,20 L120,250 Q120,258 128,258 L212,258 Q220,258 220,250 L220,20', INK, 2);
    L.forEach(([n, d, c], i) => { const y = 60 + i * 50; s += `<rect x="121" y="${y}" width="98" height="50" fill="${c}" opacity=".75"/>` + tx(240, y + 22, n, { c: INK, w: 700 }) + tx(240, y + 38, d.toFixed(2) + ' g/cm³', { f: 'var(--f-mono)', fs: 11.5 }); });
    s += circ(150, 56, 9, '#F2F2F0', INK) + tx(20, 60, 'cork 0.24', { fs: 11 }) + circ(185, 106, 8, C1, INK) + tx(20, 110, 'plastic 0.95', { fs: 11 }) + circ(155, 208, 8, '#6BAA3A', INK) + tx(20, 212, 'grape 1.2', { fs: 11 }) + `<rect x="178" y="244" width="16" height="12" fill="#9AA3AC" stroke="${INK}"/>` + tx(20, 252, 'metal nut 7.9', { fs: 11 });
    s += arrow(400, 250, 400, 60, MUT, 1.4) + tx(410, 150, 'less', { fs: 11 }) + tx(410, 164, 'dense', { fs: 11 });
    return svg(460, 268, s, 'A density column') + cap('Liquids that do not mix settle in order of density, densest at the bottom. Each object floats on the first liquid that is denser than it.'); },

  /* ---------- Unit 5 ---------- */
  floatsink: () => { let s = `<rect x="10" y="80" width="520" height="130" fill="${WATER}"/>` + ln(10, 80, 530, 80, WATERL, 2);
    s += box(90, 56, 70, 50, '#C8A26A') + arrow(125, 106, 125, 150, C1, 3) + tx(133, 146, 'weight 6 N', { c: C1, fs: 11.5, w: 700 }) + arrow(125, 56, 125, 16, C5, 3) + tx(133, 26, 'upthrust 6 N', { c: C5, fs: 11.5, w: 700 }) + tx(125, 196, 'FLOATS: upthrust = weight', { a: 'middle', c: INK, w: 700 });
    s += box(370, 130, 60, 44, '#8C7A6B') + arrow(400, 174, 400, 230 - 6, C1, 3) + tx(408, 222, 'weight 8 N', { c: C1, fs: 11.5, w: 700 }) + arrow(400, 130, 400, 104, C5, 3) + tx(408, 112, 'upthrust 3 N', { c: C5, fs: 11.5, w: 700 }) + tx(400, 70, 'SINKS: weight > upthrust', { a: 'middle', c: INK, w: 700 });
    return svg(540, 240, s, 'Floating and sinking') + cap('A floating object sinks in only until the upthrust equals its weight. A sinking object still feels upthrust, but even fully under water the upthrust is less than its weight.'); },
  k_depth: recap('depth', 'Pressure in a liquid acts in all directions and increases with depth, because there is more liquid above pushing down. The push on the bottom of an object is bigger than on its top — that difference is upthrust.', s => s.replace(/<text[^>]*>p = hρg \(Higher\)<\/text>/, '')),
  upthrustexp: () => { let s = ''; const nm = (x, rd) => ln(x, 10, x, 20, INK, 2) + box(x - 22, 20, 44, 70, 'var(--surface-2)', INK, 8) + tx(x, 60, rd, { a: 'middle', fs: 11, c: C1, w: 700 }) + ln(x, 90, x, 110, INK, 1.4);
    s += nm(90, '5.0 N') + box(72, 110, 36, 40, '#9AA3AC') + tx(90, 176, 'in air: 5.0 N', { a: 'middle', c: INK, w: 700 });
    s += nm(300, '3.0 N') + pth('M240,90 L240,210 L380,210 L380,90 M380,104 L412,120', INK, 2) + `<rect x="241" y="104" width="138" height="105" fill="${WATER}"/>` + box(282, 140, 36, 40, '#9AA3AC') + ln(300, 110, 300, 140, INK, 1.4) + pth('M398,132 L398,196 L446,196 L446,132', INK, 1.6) + `<rect x="399" y="166" width="46" height="29" fill="${WATER}"/>` + pth('M414,122 l0,30', C5, 1.4, 'none', '2 3');
    s += tx(310, 234, 'in water: 3.0 N', { a: 'middle', c: INK, w: 700 }) + tx(470, 170, 'displaced water', { fs: 11 }) + tx(470, 186, 'weighs 2.0 N', { fs: 11, c: C5, w: 700 });
    s += tx(150, 262, 'upthrust = 5.0 − 3.0 = 2.0 N = weight of water displaced', { c: C5, w: 700, fs: 13 });
    return svg(580, 275, s, 'Measuring upthrust') + cap('The newton meter reading drops when the block is lowered into water. The drop (the upthrust) equals the weight of the water pushed out of the eureka can — Archimedes’ principle.'); },
  ship: () => { let s = `<rect x="10" y="110" width="520" height="90" fill="${WATER}"/>` + ln(10, 110, 530, 110, WATERL, 2);
    s += `<rect x="70" y="150" width="34" height="34" fill="#5B6C79" stroke="${INK}"/>` + tx(87, 214, 'steel block: sinks', { a: 'middle', c: INK, fs: 11.5 }) + tx(87, 228, '7.8 g/cm³', { a: 'middle', fs: 11, f: 'var(--f-mono)' });
    s += pth('M230,86 L470,86 L446,134 L254,134 Z', INK, 2, '#5B6C79') + pth('M240,92 L460,92 L440,128 L260,128 Z', 'none', 0, 'color-mix(in srgb, var(--surface) 80%, transparent)') + tx(350,115,'air', { a: 'middle', c: INK }) + arrow(350, 170, 350, 138, C5, 3) + tx(360, 166, 'big upthrust', { c: C5, fs: 11.5, w: 700 }) + tx(350, 214, 'steel ship: floats', { a: 'middle', c: INK, fs: 11.5 }) + tx(350, 228, 'average density < 1 g/cm³', { a: 'middle', fs: 11 });
    return svg(540, 240, s, 'Why steel ships float') + cap('A hollow steel hull full of air has a low average density (total mass ÷ total volume) and displaces a huge volume of water, so the upthrust can balance its weight.'); },

  /* ---------- Unit 6 ---------- */
  storeicons: () => { const S = [['kinetic', C1, 'moving'], ['gravitational potential', C3, 'raised up'], ['elastic potential', C2, 'stretched'], ['thermal', C6, 'hot'], ['chemical', C8, 'fuel, food'], ['nuclear', C7, 'atomic nuclei'], ['magnetic', C5, 'magnets'], ['electrostatic', C4, 'charges']]; let s = '';
    S.forEach(([n, c, e], i) => { const x = 10 + (i % 4) * 135, y = 10 + Math.floor(i / 4) * 64; s += `<rect x="${x}" y="${y}" width="125" height="54" rx="10" fill="color-mix(in srgb, ${c} 14%, transparent)" stroke="${c}" stroke-width="1.6"/>` + tx(x + 62, y + 24, n, { a: 'middle', c: INK, w: 700, fs: n.length > 16 ? 10.5 : 12 }) + tx(x + 62, y + 42, e, { a: 'middle', fs: 11 }); });
    return svg(550, 140, s, 'The energy stores') + cap('The eight energy stores. Energy is measured in joules (J) and is moved between stores — it is never created or destroyed.'); },
  k_stores: recap('stores', 'A ball thrown upwards: energy moves from the kinetic store to the gravitational potential store and back again. (Ignoring air resistance, the total stays the same.)', s => s.replace(/>Eₖ</g, '>KE<').replace(/>Eₚ</g, '>GPE<')),
  transferdiag: () => { let s = ''; const B = (x, y, t, c) => `<rect x="${x}" y="${y}" width="${x > 300 ? 170 : 120}" height="44" rx="10" fill="color-mix(in srgb, ${c} 14%, transparent)" stroke="${c}" stroke-width="1.6"/>` + tx(x + (x > 300 ? 85 : 60), y + 18, t[0], { a: 'middle', c: INK, w: 700, fs: 11.5 }) + tx(x + (x > 300 ? 85 : 60), y + 34, t[1], { a: 'middle', fs: 10.5 });
    s += B(10, 60, ['chemical store', 'of the battery'], C8) + arrow(130, 82, 196, 82, INK, 2) + tx(163, 74, 'electrically', { a: 'middle', fs: 10.5, c: INK }) + box(198, 64, 96, 36, 'var(--surface-2)', INK, 18) + tx(246, 87, 'torch bulb', { a: 'middle', c: INK, w: 700, fs: 11.5 });
    s += arrow(294, 76, 380, 36, C2, 2) + tx(330, 40, 'light', { fs: 10.5, c: C2 }) + B(382, 14, ['thermal store', 'of surroundings (useful: light)'], C2) + arrow(294, 90, 380, 120, C6, 2) + tx(318, 124, 'heating', { fs: 10.5, c: C6 }) + B(382, 104, ['thermal store', 'of surroundings (wasted)'], C6);
    return svg(560, 160, s, 'An energy transfer diagram') + cap('Energy transfer diagram for a torch: boxes are stores, arrows are transfers (electrically, by light, by heating). In the end, all the energy ends up in the thermal store of the surroundings.'); },
  k_sankey: recap('sankey', 'A filament lamp: of every 100 J supplied, only 10 J becomes light (useful); 90 J heats the surroundings (wasted). The widths of the arrows show the amounts of energy.'),
  bathcup: () => { let s = pth('M20,70 Q20,150 80,150 L240,150 Q300,150 300,70 Z', INK, 2, `color-mix(in srgb, var(--u5) 25%, transparent)`) + tx(160, 108, 'bath: 40 °C', { a: 'middle', c: INK, w: 700, fs: 14 }) + tx(160, 128, '100 kg of water', { a: 'middle', fs: 11.5 });
    s += pth('M380,70 L390,150 L450,150 L460,70 Z', INK, 2, 'color-mix(in srgb, var(--u6) 30%, transparent)') + pth('M460,86 Q486,90 482,112 Q478,130 456,130', INK, 2) + tx(420, 108, '90 °C', { a: 'middle', c: INK, w: 700, fs: 14 }) + tx(420, 128, '0.25 kg', { a: 'middle', fs: 11.5 });
    s += tx(160, 176, 'lower temperature,', { a: 'middle', c: C5, w: 700, fs: 12 }) + tx(160, 192, 'MUCH more thermal energy', { a: 'middle', c: C5, w: 700, fs: 12 }) + tx(420, 176, 'higher temperature,', { a: 'middle', c: C6, w: 700, fs: 12 }) + tx(420, 192, 'less thermal energy', { a: 'middle', c: C6, w: 700, fs: 12 }) + pth('M400,60 q6,-12 0,-24 M420,60 q6,-12 0,-24 M440,60 q6,-12 0,-24', MUT, 1.5);
    return svg(560, 204, s, 'Temperature and thermal energy') + cap('Temperature tells you the average energy of the particles; thermal energy is the total energy of all of them. The bath has far more particles, so far more thermal energy.'); },
  coaster: () => { const f = x => x < 60 ? 210 - x * 2.9 : x < 120 ? 36 + (1 - Math.cos((x - 60) / 60 * Math.PI)) / 2 * 174 : x < 260 ? 210 - (1 - Math.cos((x - 120) / 140 * 2 * Math.PI)) / 2 * 110 : x < 380 ? 210 - (1 - Math.cos((x - 260) / 120 * 2 * Math.PI)) / 2 * 64 : 210; let d = ''; for (let x = 0; x <= 520; x += 4) d += (x ? 'L' : 'M') + (x + 20) + ',' + f(x).toFixed(1);
    let s = pth(d, INK, 3) + ln(20, 214, 540, 214, LN, 1);
    const lab = (x, t, c, below) => circ(x + 20, f(x) - 8, 7, c, INK, 1.4) + tx(x + 20, below ? f(x) + 22 : f(x) - 22, t, { a: 'middle', fs: 11, c: INK, w: 700 });
    s += lab(60, 'A: most GPE, slow', C3) + lab(120, 'B: fastest — most KE', C1, 1) + lab(190, 'C: lower hill', C3) + lab(320, 'D: lower again', C3) + tx(460, 204, 'brakes: KE → thermal', { a: 'middle', fs: 11, c: C6, w: 700 }) + tx(24, 252, 'lift hill: a motor fills the GPE store', { fs: 11 });
    return svg(560, 262, s, 'Energy on a rollercoaster') + cap('The lift hill fills the gravitational potential store. Going down, GPE → kinetic; climbing, kinetic → GPE. Friction and air resistance waste energy by heating, so every hill must be lower than the first.'); },

  /* ---------- Unit 7 ---------- */
  poles: () => { let s = ''; const row = (y, a, b, rep, t) => { s += magnet(40, y, 100, 26, a) + magnet(200, y, 100, 26, b) + (rep ? arrow(150, y + 13, 124, y + 13, C1, 2) + arrow(190, y + 13, 216, y + 13, C1, 2) : arrow(144, y + 13, 162, y + 13, C3, 2) + arrow(196, y + 13, 178, y + 13, C3, 2)) + tx(330, y + 18, t, { c: rep ? C1 : C3, w: 700 }); };
    row(20, false, true, true, 'N facing N: repel'); row(70, true, false, true, 'S facing S: repel'); row(120, false, false, false, 'N facing S: attract');
    return svg(520, 160, s, 'Forces between magnetic poles') + cap('Like poles repel; unlike poles attract. Only a magnet can repel another magnet, so repulsion is the test for a magnet.'); },
  k_barfield: recap('barfield', 'The field around a bar magnet: lines go from N to S, never cross, and are closest together at the poles where the field is strongest. The pattern is the same on both sides and at both ends.'),
  domains: () => { let s = ''; const bar = (x, t, al) => { s += box(x, 30, 200, 90, 'var(--surface-2)', INK, 4) + tx(x + 100, 142, t, { a: 'middle', c: INK, w: 700 }); for (let i = 0; i < 5; i++) for (let j = 0; j < 2; j++) { const cx = x + 22 + i * 39, cy = 54 + j * 42, a = al ? 0 : ((i * 7 + j * 13) % 12) / 12 * Math.PI * 2; s += `<rect x="${cx - 18}" y="${cy - 19}" width="36" height="38" fill="none" stroke="${LN}" stroke-dasharray="3 3"/>` + arrow(cx - Math.cos(a) * 12, cy - Math.sin(a) * 12, cx + Math.cos(a) * 12, cy + Math.sin(a) * 12, al ? C1 : C7, 1.8); } };
    bar(20, 'unmagnetised: domains random', false); bar(290, 'magnetised: domains lined up', true); s += tx(300, 22, 'S', { c: C6, w: 700 }) + tx(480, 22, 'N', { c: C1, w: 700 });
    return svg(510, 155, s, 'Magnetic domains') + cap('Domains are tiny regions that act like mini-magnets. In an unmagnetised bar they point every which way and cancel out; stroking or a current in a coil lines them up.'); },
  k_solenoid: recap('solenoid', 'The field of a coil (solenoid): inside it is strong and uniform (parallel lines); outside it is shaped like a bar magnet’s. The lines never cross. An iron core makes it much stronger — an electromagnet.'),
  bell: () => { let s = box(40, 60, 16, 110, 'var(--surface-2)') + [0, 1, 2, 3, 4, 5].map(i => `<ellipse cx="48" cy="${76 + i * 16}" rx="16" ry="5" fill="none" stroke="#B87333" stroke-width="2.4"/>`).join('') + tx(48, 190, 'electromagnet', { a: 'middle', fs: 11 });
    s += box(90, 60, 10, 110, '#9AA3AC') + tx(116, 186, 'iron armature', { fs: 11 }) + pth('M95,170 L95,200 L150,200', INK, 2) + pth('M150,194 l6,-6 l6,12 l6,-12 l6,12 l6,-6', C2, 1.6) + tx(150, 216, 'spring', { fs: 11 }) + ln(95, 60, 95, 30, INK, 2) + circ(95, 22, 9, INK, INK) + tx(112, 20, 'hammer', { fs: 11 });
    s += pth('M140,10 A36,36 0 0 1 176,46', C2, 5) + tx(186, 30, 'gong', { fs: 11 }) + circ(104, 120, 3, INK, INK) + ln(104, 120, 150, 120, INK, 2) + tx(160, 110, 'contact (opens when the armature moves)', { fs: 11 });
    s += wire([48, 170], [48, 240], [300, 240], [300, 120], [150, 120]) + sym('cell', 180, 240) + sym('switch (closed)', 260, 240) + wire([48, 60], [48, 44], [20, 44]);
    return svg(420, 256, s, 'An electric bell') + cap('Press the switch: the electromagnet pulls the armature, the hammer hits the gong, and the contact opens. The magnet switches off, the spring pulls the armature back, the circuit closes — and it repeats.'); },

  /* ---------- Unit 8 ---------- */
  k_moment: recap('moment', 'The moment of a force = force × perpendicular distance from the pivot. A longer spanner or a door handle far from the hinges gives a bigger moment for the same force.', s => s.replace(/<text[^>]*>d = perpendicular distance<\/text>/, '<text x="282" y="104" fill="var(--muted)" font-size="12" text-anchor="middle">d = distance from the pivot</text>')),
  seesaw: () => { let s = pth('M270,150 L250,190 L290,190 Z', INK, 2, 'var(--surface-2)') + box(50, 140, 440, 10, '#B87333', INK, 3);
    s += box(118, 110, 44, 30, C1) + tx(140, 130, '400 N', { a: 'middle', c: '#fff', w: 700, fs: 11 }) + arrow(140, 150, 140, 184, C1, 2) + box(348, 110, 44, 30, C5) + tx(370, 130, '600 N', { a: 'middle', c: '#fff', w: 700, fs: 11 }) + arrow(370, 150, 370, 184, C5, 2);
    s += ln(140, 96, 270, 96, INK, 1.2) + ln(140, 90, 140, 102, INK) + ln(270, 90, 270, 102, INK) + tx(205, 90, '1.5 m', { a: 'middle', c: INK }) + ln(270, 96, 370, 96, INK, 1.2) + ln(370, 90, 370, 102, INK) + tx(320, 90, '1.0 m', { a: 'middle', c: INK });
    s += tx(140, 214, 'anticlockwise: 400 × 1.5 = 600 Nm', { a: 'middle', c: C1, fs: 11.5, w: 700 }) + tx(390, 214, 'clockwise: 600 × 1.0 = 600 Nm', { a: 'middle', c: C5, fs: 11.5, w: 700 }) + tx(270, 236, 'equal moments → balanced', { a: 'middle', c: INK, w: 700 });
    return svg(540, 246, s, 'The principle of moments') + cap('A balanced seesaw: total clockwise moment = total anticlockwise moment. The heavier person sits closer to the pivot.'); },
  friction: () => { let s = pth('M20,150 l10,-6 l8,5 l10,-7 l9,6 l12,-5 l8,6 l10,-6 l9,5 l11,-7 l10,6 l9,-4 l10,5 l12,-6 l8,5 l10,-7 l9,6 l12,-5 l8,6 l10,-6 l9,5 l11,-7 l10,6 l9,-4 l10,5 l12,-6 l8,5 l10,-7 l9,6 l12,-5 l8,6 L420,150', INK, 1.6) + `<path d="M120,100 L300,100 L300,138 l-9,-4 l-10,6 l-12,-5 l-8,6 l-10,-6 l-9,5 l-11,-7 l-10,6 l-9,-4 l-10,5 l-12,-6 l-8,5 l-10,-7 l-9,6 l-12,-5 l-8,6 l-10,-6 L120,138 Z" fill="#C8A26A" stroke="${INK}" stroke-width="1.6"/>`;
    s += arrow(300, 118, 380, 118, C5, 3) + tx(340, 108, 'pull', { a: 'middle', c: C5, w: 700 }) + arrow(120, 142, 50, 142, C1, 3) + tx(84, 166, 'friction', { a: 'middle', c: C1, w: 700 }) + tx(210, 186, 'magnified: tiny bumps catch on each other', { a: 'middle', c: INK });
    return svg(440, 196, s, 'Friction') + cap('Surfaces are rough close up. The bumps catch as they slide, giving friction, which acts opposite to the motion and heats the surfaces.'); },
  k_dtgraph: recap('dtgraph', 'Distance–time graph: the gradient (steepness) is the speed — steeper means faster. A horizontal line means the object is stationary.'),
  pressure: () => { let s = ''; const brick = (x, w, h, t, p) => { s += box(x, 150 - h, w, h, '#C8573F', INK, 2) + tx(x + w / 2, 176, t, { a: 'middle', c: INK, w: 700, fs: 11.5 }) + tx(x + w / 2, 192, p, { a: 'middle', fs: 11, f: 'var(--f-mono)' }) + arrow(x + w / 2, 150 - h - 30, x + w / 2, 150 - h - 4, C1, 2); };
    s += ln(10, 150, 530, 150, INK, 2); brick(30, 160, 40, 'large area', '20 N ÷ 0.02 m² = 1000 Pa'); brick(260, 80, 50, 'medium area', '20 N ÷ 0.01 m² = 2000 Pa'); brick(430, 40, 90, 'small area', '4000 Pa');
    s += tx(270, 20, 'the same 20 N brick, three ways up', { a: 'middle', c: INK, w: 700 });
    return svg(540, 200, s, 'Pressure depends on area') + cap('The same force on a smaller area gives a bigger pressure: pressure = force ÷ area. Snowshoes spread the force; knives and pins concentrate it.'); },
  footprint: () => { let s = ''; for (let i = 0; i <= 14; i++) s += ln(20 + i * 14, 20, 20 + i * 14, 244, 'var(--line)', 1); for (let j = 0; j <= 16; j++) s += ln(20, 20 + j * 14, 216, 20 + j * 14, 'var(--line)', 1);
    s += pth('M118,34 C160,30 176,70 172,110 C170,140 160,160 158,190 C156,222 136,236 112,232 C86,228 78,206 82,180 C86,150 70,120 72,86 C74,52 90,36 118,34 Z', C1, 2.4, 'color-mix(in srgb, var(--u1) 12%, transparent)');
    s += tx(240, 50, 'count a square if', { c: INK }) + tx(240, 66, 'HALF OR MORE is inside', { c: INK, w: 700 }) + tx(240, 100, 'e.g. 150 squares = 150 cm²', { c: INK }) + tx(240, 124, 'both feet: 300 cm²', { c: INK }) + tx(240, 158, 'weight 450 N:', { c: INK }) + tx(240, 176, 'p = 450 ÷ 300', { c: INK, f: 'var(--f-mono)' }) + tx(240, 194, '  = 1.5 N/cm²', { c: C1, w: 700, f: 'var(--f-mono)' });
    return svg(420, 256, s, 'Finding the area of a footprint') + cap('Draw round your shoe on 1 cm squared paper and count the squares (half or more). Pressure = weight ÷ area — double the area if you stand on both feet.'); },
  hydraulic: () => { let s = pth('M60,70 L60,180 L400,180 L400,110 M100,70 L100,140 L340,140 L340,110', INK, 2) + `<path d="M61,100 L99,100 L99,141 L341,141 L341,110 L399,110 L399,179 L61,179 Z" fill="color-mix(in srgb, var(--u6) 28%, transparent)"/>`;
    s += box(58, 88, 44, 12, '#9AA3AC') + arrow(80, 40, 80, 86, C1, 3) + tx(80, 30, '50 N', { a: 'middle', c: C1, w: 700 }) + tx(80, 204, 'small piston 5 cm²', { a: 'middle', fs: 11 });
    s += box(338, 98, 64, 12, '#9AA3AC') + arrow(370, 96, 370, 40, C5, 3) + tx(370, 30, '2000 N', { a: 'middle', c: C5, w: 700 }) + tx(370, 204, 'large piston 200 cm²', { a: 'middle', fs: 11 }) + tx(220, 164, 'oil: pressure 10 N/cm² everywhere', { a: 'middle', c: INK, fs: 12, w: 700 });
    return svg(440, 214, s, 'A hydraulic jack') + cap('The liquid cannot be squashed, so the pressure made at the small piston (50 ÷ 5 = 10 N/cm²) acts on the large piston too, giving a bigger force (10 × 200 = 2000 N).'); },
  k_gasbox: recap('gasbox', 'Gas particles move fast in random directions. Each collision with the wall gives a tiny push; together they make the gas pressure. Heating makes them hit harder and more often.'),
  k_atmosphere: recap('atmosphere', 'The atmosphere is a thin layer of air that gets less dense with height. At sea level the weight of the air above gives a pressure of about 100 000 Pa; higher up there is less air above, so the pressure is lower.'),
  can: () => { let s = ''; const can = (x, y, crushed) => crushed ? pth(`M${x - 18},${y} L${x - 12},${y + 20} L${x - 20},${y + 36} L${x - 10},${y + 52} L${x - 16},${y + 70} L${x + 16},${y + 70} L${x + 10},${y + 52} L${x + 20},${y + 36} L${x + 12},${y + 20} L${x + 18},${y} Z`, INK, 1.8, '#C8CDD2') : box(x - 20, y, 40, 70, '#C8CDD2', INK, 4);
    s += tx(90, 18, '1. Heat a little water', { a: 'middle', c: INK, w: 700, fs: 11.5 }) + can(90, 50, false) + `<rect x="72" y="108" width="36" height="10" fill="${WATER}"/>` + pth('M80,46 q6,-12 0,-22 M92,46 q6,-12 0,-22 M104,46 q6,-12 0,-22', MUT, 1.4) + pth('M76,140 l6,-14 l6,14 l6,-18 l6,18 l6,-14 l6,14', C2, 2) + tx(90, 160, 'steam pushes air out', { a: 'middle', fs: 11 });
    s += tx(275, 18, '2. Flip into cold water', { a: 'middle', c: INK, w: 700, fs: 11.5 }) + `<rect x="210" y="96" width="130" height="60" fill="${WATER}"/>` + ln(210, 96, 340, 96, WATERL, 2) + `<g transform="rotate(180 275 90)">${can(275, 55, false)}</g>` + tx(275, 172, 'steam condenses', { a: 'middle', fs: 11 });
    s += tx(460, 18, '3. Crushed!', { a: 'middle', c: C1, w: 700, fs: 11.5 }) + `<rect x="395" y="96" width="130" height="60" fill="${WATER}"/>` + `<g transform="rotate(180 460 90)">${can(460, 55, true)}</g>` + [[410, 90, 436, 90], [510, 90, 484, 90], [460, 34, 460, 52]].map(([a, b, c, d]) => arrow(a, b, c, d, C1, 2)).join('') + tx(460, 172, 'air pressure outside wins', { a: 'middle', fs: 11 });
    return svg(540, 182, s, 'The crushed-can experiment') + cap('Steam drives the air out. In cold water the steam condenses, leaving almost no gas particles inside, so the pressure inside is very low. Atmospheric pressure outside crushes the can.'); },

  /* ---------- Unit 9 ---------- */
  k_symbols: () => { const K = ['cell', 'battery', 'switch (open)', 'switch (closed)', 'lamp', 'resistor', 'variable resistor', 'fuse', 'ammeter', 'voltmeter', 'motor', 'buzzer', 'two-way switch', 'LED']; let s = '';
    K.forEach((k, i) => { const x = 70 + (i % 4) * 130, y = 36 + Math.floor(i / 4) * 64; s += SYM[k](x, y) + tx(x, y + 30, k, { a: 'middle', fs: 11, c: INK, w: 600 }); });
    return svg(540, 270, s, 'Circuit symbols') + cap('The circuit symbols for Key Stage 3. On a cell, the longer line is the positive (+) terminal; a battery is two or more cells.'); },
  meters: () => { let s = wire([40, 40], [40, 150], [420, 150], [420, 40], [40, 40]) + sym('cell', 230, 40) + tx(230, 18, '3 V', { a: 'middle', c: INK }) + `<rect x="200" y="140" width="60" height="20" fill="var(--paper)"/>` + sym('lamp', 230, 150);
    s += `<rect x="100" y="30" width="60" height="20" fill="var(--paper)"/>` + sym('ammeter', 130, 40) + tx(130, 74, 'ammeter: IN SERIES', { a: 'middle', c: C5, w: 700, fs: 11.5 });
    s += wire([190, 150], [190, 200], [218, 200]) + wire([270, 150], [270, 200], [242, 200]) + dot(190, 150) + dot(270, 150) + `<rect x="200" y="190" width="60" height="20" fill="var(--paper)"/>` + sym('voltmeter', 230, 200) + tx(230, 234, 'voltmeter: IN PARALLEL (across the lamp)', { a: 'middle', c: C1, w: 700, fs: 11.5 });
    return svg(460, 244, s, 'Connecting ammeters and voltmeters') + cap('An ammeter goes in the loop (series) so the current flows through it. A voltmeter goes across a component (parallel) to compare the two ends.'); },
  ropemodel: () => { let s = `<ellipse cx="270" cy="100" rx="220" ry="62" fill="none" stroke="#B87333" stroke-width="5"/>`; for (let i = 0; i < 14; i++) { const a = i / 14 * Math.PI * 2; s += arrowHead(270 + 220 * Math.cos(a), 100 + 62 * Math.sin(a), a + Math.PI / 2, C2, 9); }
    s += person(56, 150, 1.1, C8) + tx(56, 180, 'teacher = cell', { a: 'middle', fs: 11.5, c: INK }) + person(270, 176, 1.1, C1) + tx(270, 200, 'gripping hands = lamp (resistance): hands get warm', { a: 'middle', fs: 11.5, c: INK }) + tx(270, 104, 'moving rope = current', { a: 'middle', fs: 12, c: C2, w: 700 }) + tx(270, 120, 'same speed everywhere', { a: 'middle', fs: 11 });
    return svg(540, 210, s, 'The rope model of a circuit') + cap('The rope model: the teacher (cell) pushes the rope (charge) round; it moves at the same rate all the way round (current is not used up); energy is transferred where it is gripped (the lamp).'); },
  k_series: recap('series', 'Series circuit: one loop. The current is the same everywhere; the supply p.d. is shared between the components (2.0 V + 4.0 V = 6.0 V).'),
  k_parallel: recap('parallel', 'Parallel circuit: the current splits into branches and joins again (0.50 A + 0.30 A = 0.80 A). Each branch gets the full supply p.d.'),
  wirerig: () => { let s = box(40, 60, 420, 20, 'color-mix(in srgb, var(--u2) 30%, transparent)', INK, 2); for (let i = 0; i <= 10; i++) s += ln(40 + i * 42, 60, 40 + i * 42, 68, INK, 1) + tx(40 + i * 42, 94, i * 10, { a: 'middle', fs: 9.5, f: 'var(--f-mono)' });
    s += ln(40, 70, 460, 70, C6, 2) + pth('M82,56 l-8,-14 l16,0 Z', INK, 1.4, C1) + pth('M292,56 l-8,-14 l16,0 Z', INK, 1.4, C1) + tx(187, 110, 'length between the clips (cm)', { a: 'middle', fs: 11 });
    s += wire([82, 42], [82, 20], [292, 20], [292, 42]) + `<rect x="160" y="10" width="54" height="20" fill="var(--paper)"/>` + sym('voltmeter', 187, 20);
    s += wire([82, 56], [30, 56], [30, 170], [460, 170], [460, 130], [292, 130], [292, 56]) + sym('cell', 120, 170) + sym('ammeter', 250, 170) + sym('switch (closed)', 360, 170) + tx(187, 198, 'R = V ÷ I for each length', { a: 'middle', c: INK, w: 700 });
    return svg(490, 210, s, 'Resistance of a wire') + cap('Crocodile clips set the length of wire in the circuit. Measure the current (ammeter in series) and the p.d. across the length (voltmeter in parallel); R = V ÷ I. Switch off between readings.'); },
  twoway: () => { let s = sym('cell', 60, 40) + tx(60, 16, 'supply', { a: 'middle', fs: 11 }) + wire([30, 40], [20, 40], [20, 150], [60, 150]) + wire([90, 40], [470, 40], [470, 150]) + sym('lamp', 470, 150);
    s += circ(60, 150, 3, INK, INK) + circ(100, 128, 3, INK, INK) + circ(100, 172, 3, INK, INK) + ln(60, 150, 98, 129, C1, 2.5) + wire([100, 128], [380, 128]) + wire([100, 172], [380, 172]) + circ(380, 128, 3, INK, INK) + circ(380, 172, 3, INK, INK) + circ(420, 150, 3, INK, INK) + ln(420, 150, 382, 129, C1, 2.5) + wire([420, 150], [446, 150]) + wire([470, 150 + 12], [470, 190]) ;
    s += tx(80, 206, 'switch downstairs', { a: 'middle', fs: 11, c: INK, w: 700 }) + tx(400, 206, 'switch upstairs', { a: 'middle', fs: 11, c: INK, w: 700 }) + tx(240, 120, 'two linking wires', { a: 'middle', fs: 11 }) + tx(240, 104, 'both switches up → complete → lamp ON', { a: 'middle', fs: 12, c: GOOD, w: 700 });
    return svg(520, 216, s, 'Two-way switches for a staircase light') + cap('Two two-way switches joined by two wires. When both point to the same wire the circuit is complete and the lamp is on; flicking either switch breaks it (or completes it again).'); },

  /* ---------- Unit 10 ---------- */
  k_wavetypes: recap('wavetypes', 'Sound is a longitudinal wave: particles vibrate backwards and forwards along the direction the wave travels, making compressions and rarefactions. In a transverse wave (like water ripples) they vibrate at right angles.'),
  belljar: () => { let s = pth('M120,190 L120,80 Q120,30 200,30 Q280,30 280,80 L280,190', INK, 2, GLASS) + box(90, 190, 220, 14, 'var(--surface-2)') + ln(310, 197, 400, 197, INK, 3) + box(400, 180, 70, 34, 'var(--surface-2)', INK, 6) + tx(435, 202, 'pump', { a: 'middle', c: INK, fs: 11.5 });
    s += circ(200, 120, 26, '#E8C547', INK) + ln(200, 146, 200, 190, INK, 2) + ln(230, 110, 250, 104, INK, 2) + circ(252, 103, 5, INK, INK) + tx(200, 225, 'air pumped out → sound fades', { a: 'middle', c: C1, w: 700 }) + tx(470, 60, 'you can still SEE', { a: 'end', fs: 11.5, c: INK }) + tx(470, 76, 'the hammer moving', { a: 'end', fs: 11.5, c: INK });
    return svg(480, 236, s, 'The bell-jar experiment') + cap('As air is pumped out of the jar, the ringing bell gets quieter until it can hardly be heard: sound needs particles (a medium) to travel. Light still gets through the vacuum.'); },
  thunder: () => { let s = pth('M60,20 L40,70 L58,70 L36,120', '#E8C547', 4) + ln(10, 150, 530, 150, INK, 1.5) + eyeIcon(480, 110) + person(470, 150, 1);
    s += pth('M70,60 L460,104', C2, 1.4, 'none', '6 4') + tx(260, 66, 'light: arrives almost instantly', { a: 'middle', c: C2, fs: 11.5, w: 700 }) + [120, 200, 280, 360].map(x => pth(`M${x},92 q6,10 0,20 M${x + 10},90 q8,12 0,24`, C5, 1.6)).join('') + tx(260, 132, 'sound: 330 m/s — arrives later', { a: 'middle', c: C5, fs: 11.5, w: 700 });
    s += tx(270, 176, 'count the seconds: distance ≈ 330 × time (about 1 km every 3 s)', { a: 'middle', c: INK, w: 700 });
    return svg(540, 186, s, 'Lightning and thunder') + cap('You see the flash almost straight away but the thunder travels at only 330 m/s. Every 3 seconds between flash and bang is about 1 km.'); },
  k_scope: recap('scope', 'Oscilloscope traces of sounds: a taller trace (bigger amplitude) is a louder sound; more waves across the screen (higher frequency) is a higher-pitched sound.'),
  dbscale: () => { const L = [[0, 'threshold of hearing'], [30, 'whisper'], [60, 'conversation'], [85, 'busy traffic — damage with long exposure'], [100, 'nightclub / power drill'], [120, 'jet engine at 30 m — pain'], [140, 'firework close up']]; let s = '';
    s += `<defs><linearGradient id="dbg" x1="0" x2="1"><stop offset="0" stop-color="#3DAE5B"/><stop offset=".55" stop-color="#E8A317"/><stop offset="1" stop-color="#E5484D"/></linearGradient></defs><rect x="20" y="40" width="500" height="14" rx="7" fill="url(#dbg)"/>`;
    L.forEach(([d, t], i) => { const x = 20 + d / 140 * 500; s += ln(x, 36, x, 60, INK, 1.4) + tx(x, 30, d + ' dB', { a: 'middle', fs: 10.5, f: 'var(--f-mono)', c: INK }) + tx(Math.min(x, 470), 78 + (i % 3) * 16, t, { a: i > 4 ? 'end' : 'middle', fs: 10.5 }); });
    return svg(540, 130, s, 'The decibel scale') + cap('Loudness in decibels (dB). Every 10 dB is ten times more intense. Long exposure above about 85 dB can permanently damage hearing.'); },
  sonar: () => { let s = `<rect x="10" y="60" width="520" height="160" fill="${WATER}"/>` + ln(10, 60, 530, 60, WATERL, 2) + pth('M10,220 Q140,200 260,222 T530,212 L530,236 L10,236 Z', INK, 1.4, '#C9A36B');
    s += pth('M190,40 L330,40 L310,66 L210,66 Z', INK, 1.6, 'var(--surface)') + ln(250, 40, 250, 20, INK, 1.6) + [0, 1, 2].map(i => pth(`M${228 + i * 3},${90 + i * 40} q22,8 44,0`, C5, 1.6)).join('') + arrow(240, 72, 240, 206, C5, 2) + arrow(280, 206, 280, 72, C1, 2) + tx(212, 150, 'pulse', { a: 'end', c: C5, fs: 11.5 }) + tx(292, 150, 'echo', { c: C1, fs: 11.5 });
    s += tx(420, 110, 'depth = speed × time ÷ 2', { a: 'middle', c: INK, w: 700 }) + tx(420, 130, '= 1500 × 0.8 ÷ 2 = 600 m', { a: 'middle', c: INK, f: 'var(--f-mono)', fs: 11.5 });
    return svg(540, 240, s, 'Echo sounding') + cap('A ship times how long a sound pulse takes to reach the sea bed and come back. Divide by 2 because the sound travels there and back.'); },

  /* ---------- Unit 11 ---------- */
  seeing: () => { let s = sun(50, 50) + tx(50, 92, 'luminous source', { a: 'middle', fs: 11 }) + box(250, 110, 60, 50, 'color-mix(in srgb, var(--u3) 40%, transparent)', INK, 4) + tx(280, 180, 'non-luminous book', { a: 'middle', fs: 11 }) + eyeIcon(480, 60) + tx(480, 90, 'eye', { a: 'middle', fs: 11 });
    s += arrow(72, 62, 252, 118, C2, 2) + arrow(300, 112, 462, 64, C2, 2) + arrow(70, 50, 460, 56, C2, 1.4) + tx(260, 38, 'direct light from the Sun', { a: 'middle', fs: 11, c: C2 }) + tx(96, 132, 'light from the source', { fs: 11, c: INK }) + tx(390, 110, 'reflected into the eye', { fs: 11, c: INK });
    return svg(530, 190, s, 'How we see') + cap('We see luminous objects because their light enters our eyes. We see non-luminous objects because light from a source reflects off them into our eyes. Arrows always point into the eye.'); },
  k_reflection: recap('reflection', 'The law of reflection: the angle of incidence equals the angle of reflection, both measured from the normal (the line at 90° to the mirror).'),
  k_specular: recap('specular', 'A smooth surface reflects rays all in the same direction (specular — a clear image). A rough surface scatters them (diffuse — no image).'),
  refractblock: () => { let s = box(160, 60, 200, 110, GLASS, INK, 2) + ln(210, 30, 210, 90, MUT, 1, '5 4') + ln(310, 140, 310, 200, MUT, 1, '5 4');
    s += arrow(120, 10, 210, 60, C1, 2.4) + arrow(210, 60, 310, 170, C1, 2.4) + arrow(310, 170, 400, 220, C1, 2.4) + tx(224, 46, 'normal', { fs: 10.5 }) + tx(372, 100, 'bends TOWARDS the normal', { fs: 11, c: INK, w: 700 }) + tx(372, 116, '(slows down)', { fs: 11 }) + tx(330, 212, 'bends AWAY (speeds up)', { fs: 11, c: INK, w: 700 }) + tx(40, 150, 'air', { fs: 12 }) + tx(170, 160, 'glass', { fs: 12 });
    return svg(560, 228, s, 'Refraction through a glass block') + cap('Light slows down entering glass and bends towards the normal; it speeds up leaving and bends away from the normal. It leaves parallel to the way it went in.'); },
  k_lenses: recap('lenses', 'A convex (converging) lens brings parallel rays together at the focal point F. A concave (diverging) lens spreads them out, as if they came from a focal point on the same side.'),
  eye: () => { let s = circ(250, 120, 90, 'color-mix(in srgb, var(--u11) 6%, var(--surface))', INK, 2) + pth('M166,86 Q148,120 166,154', C5, 3) + tx(118, 70, 'cornea', { c: C5, w: 700, fs: 12 }) + ln(150, 74, 164, 90, C5, 1);
    s += ln(176, 84, 176, 104, C2, 5) + ln(176, 136, 176, 156, C2, 5) + tx(120, 196, 'iris (coloured)', { c: C2, w: 700, fs: 12 }) + ln(150, 186, 174, 156, C2, 1) + tx(96, 124, 'pupil', { c: INK, w: 700, fs: 12 }) + ln(130, 120, 174, 120, INK, 1);
    s += `<ellipse cx="196" cy="120" rx="14" ry="28" fill="color-mix(in srgb, var(--u10) 30%, transparent)" stroke="${INK}" stroke-width="1.6"/>` + tx(212, 70, 'lens', { c: INK, w: 700, fs: 12 }) + ln(214, 74, 200, 94, INK, 1);
    s += pth('M300,44 A90,90 0 0 1 300,196', C1, 5) + tx(356, 60, 'retina (detects light)', { c: C1, w: 700, fs: 12 }) + pth('M336,120 L420,130', '#E8A317', 6) + tx(372, 158, 'optic nerve → brain', { c: INK, w: 700, fs: 12 });
    s += ln(40, 100, 166, 100, C3, 1.4) + ln(40, 140, 166, 140, C3, 1.4) + ln(166, 100, 340, 140, C3, 1.4) + ln(166, 140, 340, 100, C3, 1.4);
    return svg(530, 230, s, 'The human eye') + cap('The cornea and lens refract light to form an image on the retina, which sends signals along the optic nerve. The iris changes the size of the pupil to control how much light gets in.'); },
  jellylens: () => { let s = ''; const lens = (cx, w, f, lab) => { s += `<ellipse cx="${cx}" cy="80" rx="${w}" ry="46" fill="color-mix(in srgb, var(--u3) 28%, transparent)" stroke="${INK}" stroke-width="1.6"/>`; [60, 80, 100].forEach(y => s += ln(cx - 110, y, cx, y, C1, 1.6) + ln(cx, y, cx + f, 80, C1, 1.6) + ln(cx + f, 80, cx + f + (cx + f - cx) * 0.3, 80 + (80 - y) * 0.3, C1, 1.2)); s += circ(cx + f, 80, 3.5, INK, INK) + tx(cx + f / 2, 150, lab, { a: 'middle', c: INK, w: 700, fs: 11.5 }) + tx(cx + f / 2, 166, 'focal length ' + (f > 100 ? 'longer' : 'shorter'), { a: 'middle', fs: 11 }); };
    lens(120, 8, 130, 'thin jelly lens'); lens(400, 20, 60, 'fat jelly lens');
    return svg(540, 176, s, 'Jelly lenses') + cap('A fatter, more curved jelly lens bends light more, so the rays meet closer to it (shorter focal length) — like the eye’s lens becoming fatter to focus on near objects.'); },
  prism: () => { let s = pth('M200,160 L280,20 L360,160 Z', INK, 2, GLASS) + ln(20, 110, 238, 96, '#F2F2F0', 5) + ln(20, 110, 238, 96, INK, 1) + tx(40, 100, 'white light', { c: INK, fs: 12 });
    const C = ['#E5484D', '#F08C00', '#EAB308', '#3DAE5B', '#2F7FE0', '#4B3FB0', '#8B5CF6'], N = ['red', 'orange', 'yellow', 'green', 'blue', 'indigo', 'violet'];
    C.forEach((c, i) => { s += ln(238, 96, 318, 108 + i * 3, c, 2) + ln(318, 108 + i * 3, 500, 120 + i * 13, c, 3) + tx(506, 124 + i * 13, N[i], { fs: 10.5, c: INK }); });
    return svg(560, 210, s, 'Dispersion by a prism') + cap('A prism splits white light into the colours of the spectrum. Violet is refracted most and red least (ROYGBIV).'); },
  rgb: () => { let s = `<g style="mix-blend-mode:screen"><circle cx="150" cy="80" r="62" fill="#FF3030"/><circle cx="210" cy="80" r="62" fill="#30FF30"/><circle cx="180" cy="132" r="62" fill="#3060FF"/></g>`;
    s = `<rect x="70" y="0" width="220" height="210" rx="12" fill="#05070C"/>` + s + tx(310, 50, 'red + green = yellow', { c: INK, fs: 12 }) + tx(310, 76, 'red + blue = magenta', { c: INK, fs: 12 }) + tx(310, 102, 'green + blue = cyan', { c: INK, fs: 12 }) + tx(310, 128, 'all three = white', { c: INK, fs: 12, w: 700 });
    return svg(470, 214, s, 'Mixing the primary colours of light') + cap('The primary colours of light are red, green and blue. Mixed in pairs they make the secondary colours; all three together make white.'); },
  pinhole: () => { let s = box(170, 50, 260, 140, 'color-mix(in srgb, var(--ink) 8%, transparent)', INK, 2) + ln(170, 50, 170, 114, INK, 4) + ln(170, 126, 170, 190, INK, 4) + ln(430, 50, 430, 190, C2, 4) + tx(430, 212, 'screen (tracing paper)', { a: 'middle', fs: 11 }) + tx(170, 212, 'pinhole', { a: 'middle', fs: 11 });
    s += ln(60, 60, 60, 170, C3, 5) + pth('M44,76 L60,52 L76,76', C3, 3) + tx(40, 196, 'object', { fs: 11 });
    s += ln(60, 54, 430, 176, C1, 1.4) + ln(60, 170, 430, 64, C5, 1.4) + ln(430, 70, 430, 170, C3, 5) + pth('M420,154 L430,176 L440,154', C3, 3) + tx(470, 124, 'image:', { fs: 11, c: INK }) + tx(470, 140, 'upside down', { fs: 11, c: INK, w: 700 });
    return svg(560, 222, s, 'A pinhole camera') + cap('Light travels in straight lines through the pinhole: rays from the top of the object reach the bottom of the screen, so the image is inverted. A bigger hole gives a brighter but blurrier image.'); },

  /* ---------- Skills ---------- */
  k_graphskills: () => plot({ w: 470, h: 280, x: [0, 100], y: [0, 10], xt: [0, 20, 40, 60, 80, 100], yt: [0, 2, 4, 6, 8, 10], xl: 'length of wire (cm)', yl: 'resistance (Ω)', fns: [{ f: x => x / 10, c: C5, w: 2 }], marks: [[10, 1.1], [20, 1.9], [30, 3.1], [40, 4.0], [50, 6.8], [60, 6.1], [70, 6.9], [80, 8.1], [90, 9.0]].map(([x, y]) => ({ x, y, r: 3.5, c: y === 6.8 ? BAD : INK })), text: [[52, 7.6, 'anomaly — ignore it', { c: BAD, fs: 11 }], [62, 4.2, 'line of best fit', { c: C5, fs: 11.5, w: 700 }]], label: 'A good line graph', cap: 'A good line graph: independent variable on the x-axis, labelled axes with units, even scales, neat points and a line of best fit that ignores the anomaly. A straight line through the origin means directly proportional.' })
});
